   995			if grant := races.GetGrants(d.race); grant != nil {
   996				armorProfs = append(armorProfs, grant.ArmorProficiencies...)
   997				weaponProfs = append(weaponProfs, grant.WeaponProficiencies...)
   998				toolProfs = append(toolProfs, grant.ToolProficiencies...)
   999			}
  1000		}
  1001	
  1002		// TODO: Collect from background grants when implemented
  1003	
  1004		return armorProfs, weaponProfs, toolProfs
  1005	}
