   492	// SetAbilityScores sets the character's base ability scores
   493	func (d *Draft) SetAbilityScores(input *SetAbilityScoresInput) error {
   494		if input == nil {
   495			return rpgerr.New(rpgerr.CodeInvalidArgument, "input cannot be nil")
   496		}
   497	
   498		// Validate all 6 scores are present
   499		requiredAbilities := []abilities.Ability{
   500			abilities.STR, abilities.DEX, abilities.CON,
   501			abilities.INT, abilities.WIS, abilities.CHA,
   502		}
   503	
   504		for _, ability := range requiredAbilities {
   505			score, ok := input.Scores[ability]
   506			if !ok {
   507				return rpgerr.Newf(rpgerr.CodeInvalidArgument, "missing score for %s", ability)
   508			}
   509	
   510			// Validate range (3-18 for base scores)
   511			if score < 3 || score > 18 {
   512				return rpgerr.Newf(rpgerr.CodeInvalidArgument,
   513					"%s score %d is outside valid range (3-18)", ability, score)
   514			}
   515		}
   516	
   517		d.baseAbilityScores = input.Scores
   518	
   519		// Record the choice with method
   520		d.recordChoice(choices.ChoiceData{
   521			Category:              shared.ChoiceAbilityScores,
   522			Source:                shared.SourcePlayer,
   523			AbilityScoreSelection: input.Scores,
   524			Method:                input.Method,
   525		})
   526	
   527		d.updatedAt = time.Now()
   528	
   529		// Update progress
   530		d.progress.Set(ProgressAbilityScores)
   531	
   532		return nil
   533	}
