   931	// compileSkills builds the skill proficiency map
   932	func (d *Draft) compileSkills(raceData *races.Data) map[skills.Skill]shared.ProficiencyLevel {
   933		skillMap := make(map[skills.Skill]shared.ProficiencyLevel)
   934	
   935		// Add racial skill proficiencies
   936		for _, skill := range raceData.Skills {
   937			skillMap[skill] = shared.Proficient
   938		}
   939	
   940		// Add chosen skills from choices
   941		for _, choice := range d.choices {
   942			if choice.Category == shared.ChoiceSkills {
   943				for _, skill := range choice.SkillSelection {
   944					skillMap[skill] = shared.Proficient
   945				}
   946			}
   947		}
   948	
   949		// Apply expertise - upgrade proficient skills to expert
   950		for _, choice := range d.choices {
   951			if choice.Category == shared.ChoiceExpertise {
   952				for _, skill := range choice.ExpertiseSelection {
   953					// Only upgrade if already proficient (validation should catch this earlier)
   954					if _, hasProficiency := skillMap[skill]; hasProficiency {
   955						skillMap[skill] = shared.Expert
   956					}
   957				}
   958			}
   959		}
   960	
   961		// TODO: Add background skills when we have internal background data
   962	
   963		return skillMap
   964	}
