   268					fmt.Sprintf("regions[%d].id", i), "duplicate_region",
   269					"regions[%d].id %q duplicates regions[%d]", i, region.ID, first,
   270				)
   271			}
   272			seenIDs[region.ID] = i
   273			if region.Archetype != nil {
   274				if *region.Archetype == "" {
   275					return authoredError(
   276						fmt.Sprintf("regions[%d].archetype", i), "invalid_region",
