   281					return authoredError(fmt.Sprintf("regions[%d].archetype", i), "invalid_region", "regions[%d].archetype: %v", i, err)
   282				}
   283			}
   284			if region.Cells == nil {
   285				return authoredError(
   286					fmt.Sprintf("regions[%d].cells", i), "invalid_region",
   287					"regions[%d].cells is required (use [] for an empty scope)", i,
   288				)
   289			}
