    45	// CompileDungeon is the protobuf-free complete-candidate provider seam used by
    46	// API adapters. It never accepts previous compiled state or source metadata.
    47	func CompileDungeon(ctx context.Context, in *CompileDungeonInput) (*CompileDungeonOutput, error) {
