    62			field, authored := fieldErrorFor(err)
    63			if !authored {
    64				return nil, fmt.Errorf("dungeonspec: decode candidate: %w", err)
    65			}
    66			return validationOutput(field), nil
    67		}
    68		if err := Validate(spec); err != nil {
    69			field, authored := fieldErrorFor(err)
    70			if !authored {
    71				return nil, fmt.Errorf("dungeonspec: validate candidate: %w", err)
    72			}
    73			return validationOutput(field), nil
    74		}
    75		compiled, err := compileWithConfig(spec, LoadConfig{PartyStartSeatCount: in.PartyStartSeatCount})
    76		if err != nil {
    77			return nil, fmt.Errorf("dungeonspec: compile candidate: %w", err)
    78		}
