    91			// Init/generator rejections describe authored content for this complete
    92			// candidate; cancellations and provider failures remain Go errors.
    93			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
    94				return nil, err
    95			}
