   101	func validationOutput(field FieldError) *CompileDungeonOutput {
   102		return &CompileDungeonOutput{FieldErrors: []FieldError{field}}
   103	}
   104	
   105	func strictRegionValidation(compiled CompiledDungeon) *FieldError {
   106		canvas := compiled.canvas
   107		if len(canvas.floorCells) == 0 {
   108			return &FieldError{
   109				Field:   fieldCanvasFloorSource,
   110				Message: "region-union floor must not be empty in strict mode",
   111				Code:    "floor_empty",
   112			}
   113		}
   114		if canvas.entrance == nil {
   115			field := fieldCanvasFloorSource
   116			if compiled.Params.PartyStart.Anchor != nil {
   117				field = fieldStart
   118			}
   119			return &FieldError{
   120				Field: field, Message: "no floor anchor has a complete same-component party start envelope",
   121				Code: "entrance_unavailable",
   122			}
   123		}
   124		floor := make(map[[2]int]struct{}, len(canvas.floorCells))
   125		for _, cell := range canvas.floorCells {
   126			floor[[2]int{cell.Column, cell.Row}] = struct{}{}
   127		}
   128		anchor := [2]int{canvas.entrance.Column, canvas.entrance.Row}
   129		component := map[[2]int]struct{}{anchor: {}}
   130		queue := [][2]int{anchor}
   131		for len(queue) > 0 {
   132			current := queue[0]
   133			queue = queue[1:]
   134			h := canvasHex(FloorPlanCell{Column: current[0], Row: current[1]})
   135			for _, cube := range h.ToCube().GetNeighbors() {
   136				pos := core.HexFromCube(cube).ToPosition()
   137				next := [2]int{int(pos.X), int(pos.Y)}
   138				if _, ok := floor[next]; !ok {
   139					continue
   140				}
   141				if _, seen := component[next]; seen {
   142					continue
   143				}
   144				component[next] = struct{}{}
   145				queue = append(queue, next)
   146			}
   147		}
   148		if len(component) != len(floor) {
   149			return &FieldError{
   150				Field: fieldCanvasFloorSource, Message: "region-union floor must be connected in strict mode",
   151				Code: "floor_disconnected",
   152			}
   153		}
   154		return nil
   155	}
   156	
   157	func fieldErrorFor(err error) (FieldError, bool) {
   158		var placement *ValidationError
   159		if errors.As(err, &placement) {
   160			return FieldError{Field: placement.Field, Message: placement.Message, Code: "invalid_offset"}, true
   161		}
   162		var authored *authoredValidationError
   163		if !errors.As(err, &authored) {
   164			return FieldError{}, false
   165		}
   166		return FieldError{Field: authored.field, Message: authored.message, Code: authored.code}, true
   167	}
   168	
   169	func runnableFieldError(compiled CompiledDungeon, err error) FieldError {
   170		field := "rooms"
   171		if compiled.canvas != nil {
   172			field = fieldStart
   173		}
   174		return FieldError{Field: field, Message: err.Error(), Code: "not_runnable"}
   175	}
