    50	// SeedMonsters actually consume: engine params ready for InitDungeon, and
    51	// a spawn plan ready for SeedMonsters. Placements is a separate authoring
    52	// projection and is never joined to toolkit-minted runtime identity. Its
    53	// private canvas source occupancy is immutable compiler state used only by
    54	// LoadWithPrevious; no pointer aliases decoded YAML.
    55	type CompiledDungeon struct {
    56		// Params feeds Encounter.InitDungeon directly. Params.RandomSeed is
    57		// deliberately left at its zero value -- Load has no opinion on
    58		// reproducibility, so the caller MUST set it before calling
    59		// InitDungeon, or repeated encounters compiled from the same spec
    60		// bytes won't roll the same layout.
    61		Params     encounter.DungeonParams
    62		Spawns     []SpawnInstruction  // boss first, then entrance->boss chain order
    63		Placements []CompiledPlacement // stable compiler order in absolute coordinates
    64		canvas     *canvasCompiled     // private opaque prior-validation/source state
    65	}
    66	
    67	// Load decodes, validates, and compiles a spec in one call -- the only
    68	// entry point callers use. Door entity ids are COMPILER-GENERATED from
    69	// content ("<key>-door-<from>-<to>" per connector), so callers supply
    70	// nothing but the bytes.
    71	//
    72	// Expected call sequence once Load returns: enc.InitDungeon(compiled.Params)
    73	// (after setting Params.RandomSeed, see CompiledDungeon.Params), then
    74	// enc.AddPlayer for each player, then enc.SeedMonsters(compiled.Spawns) --
    75	// in that order. SeedMonsters' combat-entry check only evaluates players
    76	// already added; calling it before every AddPlayer silently skips combat
    77	// entry for that seeding pass rather than erroring, so an author-placed
    78	// monster in a party's starting sightline needs the party added first.
    79	func Load(raw []byte) (CompiledDungeon, error) {
    80		return LoadWithConfig(raw, LoadConfig{PartyStartSeatCount: normalProductPartyStartSeats})
    81	}
    82	
    83	// LoadWithConfig decodes, validates, and compiles a spec using the supplied
    84	// host party capacity. Preview and runtime should pass the same positive
    85	// PartyStartSeatCount so they build the same reservation.
    86	func LoadWithConfig(raw []byte, config LoadConfig) (CompiledDungeon, error) {
    87		if config.PartyStartSeatCount < 1 {
    88			return CompiledDungeon{}, fmt.Errorf(
    89				"party start seat count must be at least 1 (got %d)", config.PartyStartSeatCount)
    90		}
    91		spec, err := Decode(raw)
    92		if err != nil {
    93			return CompiledDungeon{}, err
    94		}
    95		if err := Validate(spec); err != nil {
    96			return CompiledDungeon{}, err
    97		}
    98		return compileWithConfig(spec, config)
    99	}
   100	
   101	// LoadWithPrevious validates candidate source against opaque prior compiled state before compiling it.
   102	func LoadWithPrevious(raw []byte, config LoadConfig, previous CompiledDungeon) (CompiledDungeon, error) {
   103		candidate, err := LoadWithConfig(raw, config)
   104		if err != nil {
   105			return CompiledDungeon{}, err
   106		}
   107		if err := validatePreviousCanvas(candidate, previous); err != nil {
   108			return CompiledDungeon{}, err
   109		}
   110		return candidate, nil
   111	}
   112	
   113	// compile assumes spec has already passed Validate -- every ref shape,
   114	// cell bound, and boss-cardinality invariant it relies on is guaranteed by
   115	// that pass. It still returns an error rather than panicking, matching
   116	// this package's style elsewhere, in case that assumption is ever violated
   117	// by a future caller.
   118	func compile(spec *DungeonSpec) (CompiledDungeon, error) {
   119		return compileWithConfig(spec, LoadConfig{PartyStartSeatCount: normalProductPartyStartSeats})
   120	}
   121	
   122	// compileWithConfig compiles a validated spec using the same host party-start
   123	// reservation supplied at LoadWithConfig's public boundary.
   124	func compileWithConfig(spec *DungeonSpec, config LoadConfig) (CompiledDungeon, error) {
   125		if spec.Canvas != nil {
   126			return compileCanvas(spec, config)
   127		}
   128		var bossRoom *RoomSpec
   129		for i := range spec.Rooms {
   130			if spec.Rooms[i].Boss != nil {
   131				bossRoom = &spec.Rooms[i]
   132				break // validateBossCardinality already guarantees exactly one
   133			}
   134		}
   135		if bossRoom == nil {
   136			return CompiledDungeon{}, fmt.Errorf("dungeon %q: no boss room (Validate should have rejected this spec)", spec.Key)
   137		}
   138	
   139		// Boss spawn goes first, regardless of the boss room's position in the
   140		// chain (design.md, defense-in-depth ahead of Slice C's own invariant).
   141		//
   142		// bossRoom.Boss.At is nil only for an unpinned boss -- Validate's M1-only
   143		// restriction (Task B2) rejects that shape today, so Load can never
   144		// reach this branch; it stays here so compile() never panics regardless
   145		// (this function's own doc), and it's exactly where M2's Task C0 lands:
   146		// an unpinned boss becomes a rolled (Count-based, no At) spawn candidate,
   147		// which is precisely what Count:1, At:nil already expresses.
   148		var bossAt *encounter.LocalHex
   149		if bossRoom.Boss.At != nil {
   150			at := encounter.LocalHex{Col: bossRoom.Boss.At[0], Row: bossRoom.Boss.At[1]}
   151			bossAt = &at
   152		}
   153		bossTargeting, err := compileTargeting(bossRoom.Boss.Targeting)
   154		if err != nil {
   155			return CompiledDungeon{}, fmt.Errorf("room %q: boss targeting: %w", bossRoom.ID, err)
   156		}
   157		// Capacity is a hint, not a bound: sized for the boss spawn plus one
   158		// per room, but a room's place list can name several monster entries
   159		// (growing past the hint) or none at all (falling short of it) --
   160		// neither direction is guaranteed.
   161		spawns := make([]SpawnInstruction, 0, len(spec.Rooms)+1)
   162		spawns = append(spawns, SpawnInstruction{
   163			RoomID:     bossRoom.ID,
   164			MonsterRef: bossRoom.Boss.Ref,
   165			Count:      1,
   166			At:         bossAt,
   167			Targeting:  bossTargeting,
   168			Offset:     clonePlacementOffset(bossRoom.Boss.Offset),
   169		})
   170	
   171		regions := make([]encounter.DungeonRegionParams, len(spec.Rooms))
   172		for i := range spec.Rooms {
   173			room := &spec.Rooms[i]
   174			region, roomSpawns, err := compileRoom(room)
   175			if err != nil {
   176				return CompiledDungeon{}, fmt.Errorf("room %q: %w", room.ID, err)
   177			}
   178			regions[i] = region
   179			spawns = append(spawns, roomSpawns...)
   180		}
   181	
   182		connectors := make([]encounter.DungeonConnectorParams, len(spec.Connectors))
   183		for i := range spec.Connectors {
   184			connectors[i] = compileConnector(spec.Key, &spec.Connectors[i])
   185		}
   186		authoredEdges, err := compileWalls(spec)
   187		if err != nil {
   188			return CompiledDungeon{}, err
   189		}
   190		placements, err := compileRoomChainPlacements(spec)
   191		if err != nil {
   192			return CompiledDungeon{}, err
   193		}
   194	
   195		partyStart := encounter.PartyStartParams{SeatCount: config.PartyStartSeatCount}
   196		if spec.Start != nil {
   197			anchor := core.HexFromPosition(spatial.Position{
   198				X: float64(spec.Start[0]),
   199				Y: float64(spec.Start[1]),
   200			})
   201			partyStart.Anchor = &anchor
   202		}
   203	
   204		return CompiledDungeon{
   205			Params: encounter.DungeonParams{
   206				Key:           spec.Key,
   207				Regions:       regions,
   208				Connectors:    connectors,
   209				Height:        spec.Height,
   210				Theme:         spec.Theme,
   211				PartyStart:    partyStart,
   212				AuthoredEdges: authoredEdges,
   213			},
   214			Spawns:     spawns,
   215			Placements: placements,
   216		}, nil
   217	}
   218	
   219	// compileRoomChainPlacements copies every authored room placement into the
   220	// absolute compiled coordinate frame without altering optional metadata.
   221	func compileRoomChainPlacements(spec *DungeonSpec) ([]CompiledPlacement, error) {
   222		var placements []CompiledPlacement
   223		startColumn := 0
   224		for roomIndex := range spec.Rooms {
   225			room := &spec.Rooms[roomIndex]
   226			for entryIndex := range room.Place {
   227				entry := &room.Place[entryIndex]
   228				refType, err := refParts(entry.Ref)
   229				if err != nil {
   230					return nil, fmt.Errorf("rooms[%d].place[%d].ref: %w", roomIndex, entryIndex, err)
   231				}
   232				facing, err := compileFacing(entry.Facing)
   233				if err != nil {
   234					return nil, fmt.Errorf("rooms[%d].place[%d].facing: %w", roomIndex, entryIndex, err)
   235				}
   236				placements = append(placements, CompiledPlacement{
   237					SourcePath: fmt.Sprintf("rooms[%d].place[%d]", roomIndex, entryIndex),
   238					Ref:        entry.Ref, At: FloorPlanCell{Column: startColumn + entry.At[0], Row: entry.At[1]},
   239					Facing: facing, Offset: clonePlacementOffset(entry.Offset),
   240					BlocksMovement: refType == refTypeProps && boolOrTrue(entry.BlocksMovement),
   241					BlocksLoS:      refType == refTypeProps && boolOrTrue(entry.BlocksLoS),
   242				})
   243			}
   244			if room.Boss != nil && room.Boss.At != nil {
   245				placements = append(placements, CompiledPlacement{
   246					SourcePath: fmt.Sprintf("rooms[%d].boss", roomIndex), Ref: room.Boss.Ref,
   247					At:     FloorPlanCell{Column: startColumn + room.Boss.At[0], Row: room.Boss.At[1]},
   248					Offset: clonePlacementOffset(room.Boss.Offset),
   249				})
   250			}
   251			startColumn += room.Width
   252			if roomIndex < len(spec.Rooms)-1 {
   253				startColumn++
   254			}
   255		}
   256		return placements, nil
   257	}
   258	
   259	func clonePlacementOffset(offset *PlacementOffset) *PlacementOffset {
   260		if offset == nil {
   261			return nil
   262		}
   263		clone := *offset
   264		return &clone
   265	}
   266	
   267	// compileRoom compiles one room's geometry/obstacles/place block. It
   268	// returns the room's placed monster spawns separately (never the boss
   269	// spawn, which compile builds directly from room.Boss) so compile can
   270	// prepend the boss spawn once, ahead of every room's placed spawns, rather
   271	// than every call site re-deriving "is this room the boss room."
   272	func compileRoom(room *RoomSpec) (encounter.DungeonRegionParams, []SpawnInstruction, error) {
   273		// room.Monsters is unreachable via Load today -- Validate's M1-only
   274		// restriction (validateM1Restrictions) rejects any non-empty
   275		// room.Monsters -- but compileRoom does not yet know how to compile
   276		// count-based rolled monsters (M2's Slice C, count-based compiling --
   277		// see plan), so it errors loudly rather than silently dropping them if
   278		// that assumption is ever violated by a future caller, mirroring
   279		// compile()'s own nil-boss.At guard.
   280		if len(room.Monsters) > 0 {
   281			return encounter.DungeonRegionParams{}, nil,
   282				fmt.Errorf("rolled monsters not compiled yet (Validate should have rejected this spec)")
   283		}
   284	
   285		region := encounter.DungeonRegionParams{
   286			ID:        room.ID,
   287			Archetype: encounter.RegionArchetype(room.Archetype),
   288			Width:     room.Width,
   289			Pattern:   compilePattern(room.Pattern),
   290		}
   291	
   292		// The boss room's own pinned boss.at cell is a MONSTER placement exactly
   293		// like a place: monster entry below -- compile() builds its
   294		// SpawnInstruction directly from room.Boss, never through this room's
   295		// Place loop, so without reserving it here separately, InitDungeon's
   296		// rolled-obstacle draw has no idea that cell is spoken for (rpg-toolkit#842
   297		// gate finding: see encounter.DungeonRegionParams.ReservedCells' doc).
   298		if room.Boss != nil && room.Boss.At != nil {
   299			region.ReservedCells = append(region.ReservedCells,
   300				encounter.LocalHex{Col: room.Boss.At[0], Row: room.Boss.At[1]})
   301		}
   302	
   303		if len(room.Obstacles) > 0 {
   304			region.Obstacles = make([]encounter.ObstacleSpec, 0, len(room.Obstacles))
   305		}
   306		for _, o := range room.Obstacles {
   307			region.Obstacles = append(region.Obstacles, encounter.ObstacleSpec{
   308				Ref:            o.Ref,
   309				Count:          o.Count,
   310				BlocksMovement: boolOrTrue(o.BlocksMovement),
   311				BlocksLoS:      boolOrTrue(o.BlocksLoS),
   312				PreferBorder:   o.PreferBorder,
   313			})
   314		}
   315	
   316		if len(room.Place) > 0 {
   317			// Capacity is an upper bound, not exact: place entries split between
   318			// props (appended below to PlacedObstacles) and monsters (appended
   319			// to spawns), so a place block that's all monsters never grows
   320			// PlacedObstacles at all.
   321			region.PlacedObstacles = make([]encounter.PlacedObstacleSpec, 0, len(room.Place))
   322		}
   323		var spawns []SpawnInstruction
   324		for _, entry := range room.Place {
   325			refType, err := refParts(entry.Ref)
   326			if err != nil {
   327				return encounter.DungeonRegionParams{}, nil, fmt.Errorf("place %q: %w", entry.Ref, err)
   328			}
   329			switch refType {
   330			case refTypeProps:
   331				facing, err := compileFacing(entry.Facing)
   332				if err != nil {
   333					return encounter.DungeonRegionParams{}, nil, fmt.Errorf("place %q facing: %w", entry.Ref, err)
   334				}
   335				region.PlacedObstacles = append(region.PlacedObstacles, encounter.PlacedObstacleSpec{
   336					Ref:            entry.Ref,
   337					At:             encounter.LocalHex{Col: entry.At[0], Row: entry.At[1]},
   338					BlocksMovement: boolOrTrue(entry.BlocksMovement),
