     1	package dungeonspec
     2	
     3	import (
     4		"context"
     5		"errors"
     6		"fmt"
     7	
     8		"github.com/KirkDiggler/rpg-toolkit/encounter/core"
     9	)
    10	
    11	// CompileMode selects structural authoring preview or runnable compilation.
    12	type CompileMode string
    13	
    14	const (
    15		// CompileModeDraft permits structurally valid non-runnable projections.
    16		CompileModeDraft CompileMode = "draft"
    17		// CompileModeStrict requires a runnable candidate.
    18		CompileModeStrict CompileMode = "strict"
    19	)
    20	
    21	const (
    22		fieldCanvasFloorSource = "canvas.floor_source"
    23		fieldStart             = "start"
    24	)
    25	
    26	// FieldError is ordered provider-authored validation feedback.
    27	type FieldError struct{ Field, Message, Code string }
    28	
    29	// CompileDungeonInput is one complete standalone authored candidate.
    30	type CompileDungeonInput struct {
    31		Source              []byte
    32		Mode                CompileMode
    33		PartyStartSeatCount int
    34		PreviewSeed         int64
    35	}
    36	
    37	// CompileDungeonOutput is either a complete result or FieldErrors. Infrastructure
    38	// failures use CompileDungeon's Go error return.
    39	type CompileDungeonOutput struct {
    40		Compiled    CompiledDungeon
    41		FloorPlan   *FloorPlan
    42		FieldErrors []FieldError
    43	}
    44	
    45	// CompileDungeon is the protobuf-free complete-candidate provider seam used by
    46	// API adapters. It never accepts previous compiled state or source metadata.
    47	func CompileDungeon(ctx context.Context, in *CompileDungeonInput) (*CompileDungeonOutput, error) {
    48		if err := ctx.Err(); err != nil {
    49			return nil, err
    50		}
    51		if in == nil {
    52			return nil, fmt.Errorf("dungeonspec: nil CompileDungeonInput")
    53		}
    54		if in.Mode != CompileModeDraft && in.Mode != CompileModeStrict {
    55			return nil, fmt.Errorf("dungeonspec: unknown compile mode %q", in.Mode)
    56		}
    57		if in.PartyStartSeatCount < 1 {
    58			return nil, fmt.Errorf("dungeonspec: PartyStartSeatCount must be at least 1")
    59		}
    60		spec, err := Decode(in.Source)
    61		if err != nil {
    62			field, authored := fieldErrorFor(err)
    63			if !authored {
    64				return nil, fmt.Errorf("dungeonspec: decode candidate: %w", err)
    65			}
    66			return validationOutput(field), nil
    67		}
    68		if err := Validate(spec); err != nil {
    69			field, authored := fieldErrorFor(err)
    70			if !authored {
    71				return nil, fmt.Errorf("dungeonspec: validate candidate: %w", err)
    72			}
    73			return validationOutput(field), nil
    74		}
    75		compiled, err := compileWithConfig(spec, LoadConfig{PartyStartSeatCount: in.PartyStartSeatCount})
    76		if err != nil {
    77			return nil, fmt.Errorf("dungeonspec: compile candidate: %w", err)
    78		}
    79		if in.Mode == CompileModeStrict && compiled.canvas != nil {
    80			if compiled.canvas.floorSource == FloorSourceRegions {
    81				if validation := strictRegionValidation(compiled); validation != nil {
    82					return validationOutput(*validation), nil
    83				}
    84			}
    85			if err := validateCompiledRuntime(ctx, compiled, in.PreviewSeed); err != nil {
    86				return validationOutput(runnableFieldError(compiled, err)), nil
    87			}
    88		}
    89		plan, err := BuildFloorPlan(ctx, BuildFloorPlanInput{Compiled: compiled, Seed: in.PreviewSeed})
    90		if err != nil {
    91			// Init/generator rejections describe authored content for this complete
    92			// candidate; cancellations and provider failures remain Go errors.
    93			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
    94				return nil, err
    95			}
    96			return validationOutput(runnableFieldError(compiled, err)), nil
    97		}
    98		return &CompileDungeonOutput{Compiled: compiled, FloorPlan: &plan}, nil
    99	}
   100	
   101	func validationOutput(field FieldError) *CompileDungeonOutput {
   102		return &CompileDungeonOutput{FieldErrors: []FieldError{field}}
   103	}
   104	
   105	func strictRegionValidation(compiled CompiledDungeon) *FieldError {
   106		canvas := compiled.canvas
   107		if len(canvas.floorCells) == 0 {
   108			return &FieldError{
   109				Field:   fieldCanvasFloorSource,
   110				Message: "region-union floor must not be empty in strict mode",
   111				Code:    "floor_empty",
   112			}
   113		}
   114		if canvas.entrance == nil {
   115			field := fieldCanvasFloorSource
   116			if compiled.Params.PartyStart.Anchor != nil {
   117				field = fieldStart
   118			}
   119			return &FieldError{
   120				Field: field, Message: "no floor anchor has a complete same-component party start envelope",
   121				Code: "entrance_unavailable",
   122			}
   123		}
   124		floor := make(map[[2]int]struct{}, len(canvas.floorCells))
   125		for _, cell := range canvas.floorCells {
   126			floor[[2]int{cell.Column, cell.Row}] = struct{}{}
   127		}
   128		anchor := [2]int{canvas.entrance.Column, canvas.entrance.Row}
   129		component := map[[2]int]struct{}{anchor: {}}
   130		queue := [][2]int{anchor}
   131		for len(queue) > 0 {
   132			current := queue[0]
   133			queue = queue[1:]
   134			h := canvasHex(FloorPlanCell{Column: current[0], Row: current[1]})
   135			for _, cube := range h.ToCube().GetNeighbors() {
   136				pos := core.HexFromCube(cube).ToPosition()
   137				next := [2]int{int(pos.X), int(pos.Y)}
   138				if _, ok := floor[next]; !ok {
   139					continue
   140				}
   141				if _, seen := component[next]; seen {
   142					continue
   143				}
   144				component[next] = struct{}{}
   145				queue = append(queue, next)
   146			}
   147		}
   148		if len(component) != len(floor) {
   149			return &FieldError{
   150				Field: fieldCanvasFloorSource, Message: "region-union floor must be connected in strict mode",
   151				Code: "floor_disconnected",
   152			}
   153		}
   154		return nil
   155	}
   156	
   157	func fieldErrorFor(err error) (FieldError, bool) {
   158		var placement *ValidationError
   159		if errors.As(err, &placement) {
   160			return FieldError{Field: placement.Field, Message: placement.Message, Code: "invalid_offset"}, true
   161		}
   162		var authored *authoredValidationError
   163		if !errors.As(err, &authored) {
   164			return FieldError{}, false
   165		}
   166		return FieldError{Field: authored.field, Message: authored.message, Code: authored.code}, true
   167	}
   168	
   169	func runnableFieldError(compiled CompiledDungeon, err error) FieldError {
   170		field := "rooms"
   171		if compiled.canvas != nil {
   172			field = fieldStart
   173		}
   174		return FieldError{Field: field, Message: err.Error(), Code: "not_runnable"}
   175	}
