   651	func compileEnvelope(floorCells []core.Hex) []encounter.GeneratedEdge {
   652		floor := make(map[core.Hex]struct{}, len(floorCells))
   653		for _, cell := range floorCells {
   654			floor[cell] = struct{}{}
   655		}
   656		seen := make(map[wallEdgeKey]struct{})
   657		var edges []encounter.GeneratedEdge
   658		for owner := range floor {
   659			for _, cube := range owner.ToCube().GetNeighbors() {
   660				neighbor := core.HexFromCube(cube)
   661				if _, ok := floor[neighbor]; ok {
   662					continue
   663				}
   664				from, to := owner, neighbor
   665				if wallHexLess(to, from) {
   666					from, to = to, from
   667				}
   668				key := newWallEdgeKey(from, to)
   669				if _, duplicate := seen[key]; duplicate {
   670					continue
   671				}
   672				seen[key] = struct{}{}
   673				edges = append(edges, encounter.GeneratedEdge{From: from, To: to, Kind: encounter.GeneratedEdgeKindSolid})
   674			}
   675		}
   676		sort.Slice(edges, func(i, j int) bool {
   677			if wallHexLess(edges[i].From, edges[j].From) {
   678				return true
   679			}
   680			if wallHexLess(edges[j].From, edges[i].From) {
   681				return false
   682			}
   683			return wallHexLess(edges[i].To, edges[j].To)
   684		})
   685		return edges
   686	}
