   182	func validateCanvas(spec *DungeonSpec) error {
   183		if spec.Canvas.Width < 1 {
   184			return authoredError("canvas.width", "invalid_dimension", "canvas width must be positive, got %d", spec.Canvas.Width)
   185		}
   186		if spec.Canvas.Height < 1 {
   187			return authoredError(
   188				"canvas.height", "invalid_dimension", "canvas height must be positive, got %d", spec.Canvas.Height,
   189			)
   190		}
   191		cellCount, err := encounter.ValidateCanvasDimensions(spec.Canvas.Width, spec.Canvas.Height)
   192		if err != nil {
   193			return authoredError("canvas", "invalid_dimension", "%v", err)
   194		}
   195		if spec.roomsShape != roomsSequence || len(spec.Rooms) != 0 {
   196			return authoredError(
   197				"rooms", "invalid_canvas_rooms", "canvas mode rooms must be an explicit empty sequence (rooms: [])",
   198			)
   199		}
   200		if len(spec.Connectors) != 0 {
   201			return authoredError("connectors", "unsupported_capability", "canvas mode does not support connectors")
   202		}
   203		bounds := make(map[[2]int]struct{}, cellCount)
   204		for c := 0; c < spec.Canvas.Width; c++ {
   205			for r := 0; r < spec.Canvas.Height; r++ {
   206				bounds[[2]int{c, r}] = struct{}{}
   207			}
   208		}
   209		if err := validateRegions(spec.Regions, bounds); err != nil {
   210			return err
   211		}
   212		floor := bounds
   213		switch spec.Canvas.FloorSource {
   214		case "", string(FloorSourceBounds):
   215		case string(FloorSourceRegions):
   216			floor = make(map[[2]int]struct{})
   217			for _, region := range spec.Regions {
   218				for _, cell := range region.Cells {
   219					floor[cell] = struct{}{}
   220				}
   221			}
   222		default:
   223			return authoredError(
   224				"canvas.floor_source", "invalid_floor_source", "invalid floor source %q (must be %q or %q)",
   225				spec.Canvas.FloorSource, FloorSourceBounds, FloorSourceRegions,
   226			)
   227		}
   228		occupied := map[[2]int]string{}
   229		for i, e := range spec.Place {
   230			path := fmt.Sprintf("place[%d]", i)
   330	}
   331	func validateCanvasPlacement(path string, e PlacedEntry) error {
   332		typ, err := refParts(e.Ref)
   333		if err != nil {
   334			return authoredError(path+".ref", "invalid_ref", "%s.ref: %v", path, err)
   335		}
   336		if typ != refTypeProps && typ != refTypeMonsters {
   337			return authoredError(path+".ref", "invalid_ref", "%s.ref %q must be props or monsters", path, e.Ref)
   338		}
   339		if e.Facing != nil {
   340			if typ != refTypeProps || !isFloorMount(e.Mount) {
   341				return authoredError(
   342					path+".facing", "unsupported_capability", "%s.facing: %s: %s",
   343					path, unsupportedCapability, facingFloorPropsOnly,
   344				)
   345			}
   346			if err := validateFacing(*e.Facing); err != nil {
   347				return authoredError(path+".facing", "invalid_facing", "%s.facing: %v", path, err)
   348			}
   349		}
   350		if !isFloorMount(e.Mount) {
   351			return authoredError(
   352				path+".mount", "unsupported_capability", "%s.mount: %s: mounted placements are not supported",
   353				path, unsupportedCapability,
   354			)
   355		}
   356		if typ == refTypeProps && e.Targeting != nil {
   357			return authoredError(path+".targeting", "invalid_targeting", "%s.targeting: only valid on monsters", path)
   358		}
   359		if typ == refTypeMonsters {
   360			if _, ok := monsters.ByRef(e.Ref); !ok {
   361				return authoredError(
   362					path+".ref", "invalid_ref", "%s.ref %q: unknown monster ref (known: %s)",
   363					path, e.Ref, strings.Join(monsters.Refs(), ", "),
   364				)
   365			}
   366			if e.BlocksMovement != nil {
   367				return authoredError(path+".blocks_movement", "invalid_placement", "%s.blocks_movement: only valid on props", path)
   368			}
   369			if e.BlocksLoS != nil {
   370				return authoredError(path+".blocks_los", "invalid_placement", "%s.blocks_los: only valid on props", path)
   371			}
   372			if e.Targeting != nil {
   373				if _, err := monster.ParseTargetingStrategy(*e.Targeting); err != nil {
   374					return authoredError(path+".targeting", "invalid_targeting", "%s.targeting: %v", path, err)
   375				}
   376			}
   377		}
   378		return nil
   379	}
