   394	// validateM1Restrictions enforces the M1-only monster/boss.at pinning
   395	// restriction (design.md, Task B2's "M1-only monster-pinning restriction"):
   396	// SeedMonsters only handles At-bearing spawns until M2's Task C0 lands
   397	// count-based rolling, so a spec using count-based monsters: or an unpinned
   398	// boss.at would compile but fail at runtime — the exact gap the load-time
   399	// contract exists to prevent. Both checks live in this one function so
   400	// C0 can lift the restriction as a pure deletion of this function and its
   401	// one call site in Validate (the boss-required non-nil check in
   402	// validateBossCardinality is a separate, permanent check C0 never touches).
   403	func validateM1Restrictions(spec *DungeonSpec, bossRoom *RoomSpec) error {
   404		for i := range spec.Rooms {
