   406				return authoredError(
   407					fmt.Sprintf("rooms[%d].monsters", i), "unsupported_capability",
   408					"rolled monster placement lands in M2",
   409				)
   410			}
   411		}
   412		if bossRoom.Boss.At == nil {
   413			index := roomPointerIndex(spec.Rooms, bossRoom)
   414			return authoredError(
   415				fmt.Sprintf("rooms[%d].boss.at", index), "unsupported_capability",
   416				"rolled monster placement lands in M2",
   417			)
   418		}
   419		return nil
   420	}
