   376	// compilePattern maps the spec's author-facing pattern vocabulary
   377	// (patternEmpty/patternScattered, validate.go) onto the engine's own.
   378	//
   379	// PATTERN-DEFAULT TRAP: the engine treats an empty DungeonRegionParams.
   380	// Pattern as PatternRandom, but the spec's default -- "" or patternEmpty
   381	// -- means no interior walls at all, so the zero value must never pass
   382	// through unmapped. This is the one place that mapping happens; anything
   383	// that wants to reason about it again should point back here rather than
   384	// re-deriving it.
   385	func compilePattern(pattern string) string {
   386		switch pattern {
   387		case patternScattered:
   388			return environments.PatternRandom
   389		default: // "", patternEmpty, and (Validate having already run) nothing else
   390			return environments.PatternEmpty
   520	func compileCanvas(spec *DungeonSpec, config LoadConfig) (CompiledDungeon, error) {
   521		if _, err := encounter.ValidateCanvasDimensions(spec.Canvas.Width, spec.Canvas.Height); err != nil {
   522			return CompiledDungeon{}, err
   523		}
   524		edges, err := compileWalls(spec)
   525		if err != nil {
   526			return CompiledDungeon{}, err
   527		}
   528		cc := &canvasCompiled{
   529			width: spec.Canvas.Width, height: spec.Canvas.Height,
   530			floorSource: FloorSource(spec.Canvas.FloorSource),
   531		}
   532		if cc.floorSource == "" {
   533			cc.floorSource = FloorSourceBounds
   534		}
   535		floorSet := make(map[[2]int]struct{})
   536		if cc.floorSource == FloorSourceRegions {
   537			for _, region := range spec.Regions {
   538				for _, cell := range region.Cells {
   539					floorSet[cell] = struct{}{}
   540				}
   541			}
   542		} else {
   543			for col := 0; col < spec.Canvas.Width; col++ {
   544				for row := 0; row < spec.Canvas.Height; row++ {
   545					floorSet[[2]int{col, row}] = struct{}{}
   546				}
   547			}
   548		}
   549		for cell := range floorSet {
   550			cc.floorCells = append(cc.floorCells, FloorPlanCell{Column: cell[0], Row: cell[1]})
   551		}
   552		sort.Slice(cc.floorCells, func(i, j int) bool { return floorPlanCellLess(cc.floorCells[i], cc.floorCells[j]) })
   553		floorHexes := make([]core.Hex, len(cc.floorCells))
   554		for index, cell := range cc.floorCells {
   555			floorHexes[index] = canvasHex(cell)
   556		}
   557		cc.envelope = compileEnvelope(floorHexes)
   558	
   559		semanticRegions := make([]encounter.SemanticRegionParams, len(spec.Regions))
   560		for index, region := range spec.Regions {
   561			cells := make([]core.Hex, 0, len(region.Cells))
   562			seen := make(map[[2]int]struct{}, len(region.Cells))
   563			for _, cell := range region.Cells {
   564				if _, duplicate := seen[cell]; duplicate {
   565					continue
   566				}
   567				seen[cell] = struct{}{}
   568				cells = append(cells, canvasHex(FloorPlanCell{Column: cell[0], Row: cell[1]}))
   569			}
   570			sort.Slice(cells, func(i, j int) bool { return floorPlanCellLess(cellFromHex(cells[i]), cellFromHex(cells[j])) })
   571			var archetype *encounter.RegionArchetype
   572			if region.Archetype != nil {
   573				value := encounter.RegionArchetype(*region.Archetype)
   574				archetype = &value
   575			}
   576			semanticRegions[index] = encounter.SemanticRegionParams{
   577				ID: region.ID, Name: region.Name, Archetype: archetype, Cells: cells,
   578			}
   579			for _, cell := range region.Cells {
   580				cc.regionCells = append(cc.regionCells, namedCanvasCell{name: region.ID, cell: cell})
   581			}
   582		}
   583		params := encounter.DungeonParams{
   584			Key: spec.Key, Width: spec.Canvas.Width, Height: spec.Canvas.Height, Theme: spec.Theme,
   585			SemanticRegions: semanticRegions, FloorCells: floorHexes, EnvelopeEdges: cc.envelope,
   586			FloorSource: encounter.FloorSourceCanvas, RequireConnectedFloor: cc.floorSource == FloorSourceRegions,
   587			PartyStart: encounter.PartyStartParams{SeatCount: config.PartyStartSeatCount}, AuthoredEdges: edges,
   588		}
   589		if spec.Start != nil {
   590			anchor := canvasHex(FloorPlanCell{Column: spec.Start[0], Row: spec.Start[1]})
   591			params.PartyStart.Anchor = &anchor
   592		}
   593		spawns := make([]SpawnInstruction, 0, len(spec.Place))
   594		placements := make([]CompiledPlacement, 0, len(spec.Place))
   595		for index, entry := range spec.Place {
   596			refType, err := refParts(entry.Ref)
   597			if err != nil {
   598				return CompiledDungeon{}, fmt.Errorf("place[%d]: %w", index, err)
   599			}
   600			atCell := FloorPlanCell{Column: entry.At[0], Row: entry.At[1]}
   601			at := canvasHex(atCell)
   602			cc.occupancy = append(cc.occupancy, canvasSourceOccupancy{source: fmt.Sprintf("place[%d]", index), cell: entry.At})
   603			facing, err := compileFacing(entry.Facing)
   604			if err != nil {
   605				return CompiledDungeon{}, fmt.Errorf("place[%d].facing: %w", index, err)
   606			}
   607			placements = append(placements, CompiledPlacement{
   608				SourcePath: fmt.Sprintf("place[%d]", index), Ref: entry.Ref, At: atCell,
   609				Facing: facing, Offset: clonePlacementOffset(entry.Offset),
   610				BlocksMovement: refType == refTypeProps && boolOrTrue(entry.BlocksMovement),
   611				BlocksLoS:      refType == refTypeProps && boolOrTrue(entry.BlocksLoS),
   612			})
   613			switch refType {
   614			case refTypeProps:
   615				params.AbsolutePlacedObstacles = append(params.AbsolutePlacedObstacles, encounter.AbsolutePlacedObstacleSpec{
   616					ID: core.EntityID(fmt.Sprintf("canvas-prop-%d", index)), Ref: entry.Ref, At: at,
   617					BlocksMovement: boolOrTrue(entry.BlocksMovement), BlocksLoS: boolOrTrue(entry.BlocksLoS),
   618					Facing: facing, Offset: clonePlacementOffset(entry.Offset),
   619				})
   620			case refTypeMonsters:
   621				absoluteAt := at
   622				targeting, err := compileTargeting(entry.Targeting)
   623				if err != nil {
   624					return CompiledDungeon{}, fmt.Errorf("place[%d].targeting: %w", index, err)
   625				}
   626				spawns = append(spawns, SpawnInstruction{
   627					MonsterRef: entry.Ref, Count: 1, AbsoluteAt: &absoluteAt, Targeting: targeting,
   628					Offset: clonePlacementOffset(entry.Offset),
   629				})
   630				params.AbsoluteReservedCells = append(params.AbsoluteReservedCells, encounter.AbsoluteReservedCell{
   631					At: at, Name: fmt.Sprintf("placed monster %q (place[%d])", entry.Ref, index),
   632				})
   633			default:
   634				return CompiledDungeon{}, fmt.Errorf("place[%d].ref %q must be props or monsters", index, entry.Ref)
   635			}
   636		}
   637		for index, wall := range spec.Walls {
   638			cc.occupancy = append(cc.occupancy,
   639				canvasSourceOccupancy{source: fmt.Sprintf("walls[%d].from", index), cell: *wall.From},
   640				canvasSourceOccupancy{source: fmt.Sprintf("walls[%d].to", index), cell: *wall.To},
   641			)
   642		}
   643		if spec.Start != nil {
   644			cc.occupancy = append(cc.occupancy, canvasSourceOccupancy{source: "start", cell: *spec.Start})
   645		}
   646		cc.regions = compileFloorPlanRegions(spec.Regions)
   647		cc.entrance = resolveDraftEntrance(cc.floorCells, spec.Start, spec.Place, config.PartyStartSeatCount)
   648		return CompiledDungeon{Params: params, Spawns: spawns, Placements: placements, canvas: cc}, nil
   649	}
