   688	func compileFloorPlanRegions(regions []RegionSpec) []FloorPlanRegion {
   689		out := make([]FloorPlanRegion, len(regions))
   690		sets := make([]map[[2]int]struct{}, len(regions))
   691		for i, region := range regions {
   692			sets[i] = make(map[[2]int]struct{}, len(region.Cells))
   693			out[i] = FloorPlanRegion{ID: region.ID, Name: cloneString(region.Name), Archetype: cloneString(region.Archetype)}
