    26	// Config holds dependencies for the orchestrator
    27	type Config struct {
    28		DraftRepo        characterdraft.Repository
    29		CharacterRepo    characterrepo.Repository
    30		DiceService      dice.Service
    31		IDGenerator      idgen.Generator
    32		DraftIDGenerator idgen.Generator
    33	}
    34	
    35	// Validate ensures all required dependencies are present
    36	func (c *Config) Validate() error {
    37		if c.DraftRepo == nil {
    38			return apierr.InvalidArgument("draft repository is required")
    39		}
    40		if c.CharacterRepo == nil {
    41			return apierr.InvalidArgument("character repository is required")
    42		}
    43		if c.DiceService == nil {
    44			return apierr.InvalidArgument("dice service is required")
    45		}
    46		if c.IDGenerator == nil {
    47			return apierr.InvalidArgument("ID generator is required")
    48		}
    49		if c.DraftIDGenerator == nil {
    50			return apierr.InvalidArgument("draft ID generator is required")
    51		}
    52		return nil
    53	}
    54	
    55	// Orchestrator implements the character service
    56	type Orchestrator struct {
    57		draftRepo     characterdraft.Repository
    58		characterRepo characterrepo.Repository
    59		diceService   dice.Service
    60		idGen         idgen.Generator
    61		draftIDGen    idgen.Generator
    62	}
    63	
    64	// New creates a new character orchestrator
    65	func New(cfg *Config) (*Orchestrator, error) {
    66		if cfg == nil {
    67			return nil, apierr.InvalidArgument("config is required")
    68		}
    69		if err := cfg.Validate(); err != nil {
    70			return nil, err
    71		}
    72	
    73		return &Orchestrator{
    74			draftRepo:     cfg.DraftRepo,
    75			characterRepo: cfg.CharacterRepo,
    76			diceService:   cfg.DiceService,
    77			idGen:         cfg.IDGenerator,
    78			draftIDGen:    cfg.DraftIDGenerator,
    79		}, nil
    80	}
    81	
    82	// CreateDraft creates a new character draft
    83	func (o *Orchestrator) CreateDraft(ctx context.Context, input *CreateDraftInput) (*CreateDraftOutput, error) {
    84		if input == nil {
    85			return nil, apierr.InvalidArgument("input is required")
    86		}
    87		if input.PlayerID == "" {
    88			return nil, apierr.InvalidArgument("player ID is required")
    89		}
    90	
    91		// Create new draft with generated ID
    92		draftConfig := &character.DraftConfig{
    93			ID:       o.draftIDGen.Generate(),
    94			PlayerID: input.PlayerID,
    95		}
    96	
    97		draft, err := character.NewDraft(draftConfig)
    98		if err != nil {
    99			return nil, fmt.Errorf("failed to create draft: %w", err)
   100		}
   101	
   102		// Wrap in entity for storage (no appearance yet)
   103		draftEntity := &entities.CharacterDraft{
   104			Data:       draft.ToData(),
   105			Appearance: nil,
   106		}
   107	
   108		// Save to repository
   109		if _, err := o.draftRepo.Create(ctx, characterdraft.CreateInput{
   110			Draft: draftEntity,
   111		}); err != nil {
   112			return nil, fmt.Errorf("failed to save draft: %w", err)
   113		}
   114	
   115		return &CreateDraftOutput{
   116			Draft: draft.ToData(),
   117		}, nil
   118	}
