   121	func (o *Orchestrator) GetDraft(ctx context.Context, input *GetDraftInput) (*GetDraftOutput, error) {
   122		if input == nil {
   123			return nil, apierr.InvalidArgument("input is required")
   124		}
   125		if input.DraftID == "" {
   126			return nil, apierr.InvalidArgument("draft ID is required")
   127		}
   128	
   129		getOutput, err := o.draftRepo.Get(ctx, characterdraft.GetInput{
   130			ID: input.DraftID,
   131		})
   132		if err != nil {
   133			return nil, fmt.Errorf("failed to get draft: %w", err)
   134		}
   135	
   136		// Draft entity now includes appearance
   137		return &GetDraftOutput{
   138			Draft:    getOutput.Draft,
   139			Progress: getOutput.Draft.Data.Progress,
   140		}, nil
   141	}
