   150		}
   151	
   152		if _, err := o.draftRepo.Delete(ctx, characterdraft.DeleteInput{
   153			ID: input.DraftID,
   154		}); err != nil {
   155			return nil, fmt.Errorf("failed to delete draft: %w", err)
   156		}
