   163	// GetRequirements returns the requirements for character creation choices
   164	func (o *Orchestrator) GetRequirements(_ context.Context, input *GetRequirementsInput) (*GetRequirementsOutput, error) {
   165		if input == nil {
   166			return nil, apierr.InvalidArgument("input is required")
   167		}
   168	
   169		// Default to level 1 if not specified
   170		level := input.Level
   171		if level == 0 {
   172			level = 1
   173		}
   174	
   175		var requirements *choices.Requirements
   176	
   177		// Get class requirements if class is specified
   178		if input.Class != "" {
   179			// Use subclass-aware requirements if subclass is provided
   180			if input.Subclass != "" {
   181				requirements = choices.GetClassRequirementsWithSubclass(input.Class, level, input.Subclass)
   182			} else {
   183				requirements = choices.GetClassRequirementsAtLevel(input.Class, level)
   184			}
   185		}
   186	
   187		// Get race requirements if race is specified
   188		if input.Race != "" {
   189			raceReqs := choices.GetRaceRequirements(input.Race)
   190			if requirements == nil {
   191				requirements = raceReqs
   192			} else {
   193				// Merge race requirements into class requirements
   194				if raceReqs.Skills != nil {
   195					requirements.Skills = raceReqs.Skills
   196				}
   197				if raceReqs.Languages != nil {
   198					requirements.Languages = raceReqs.Languages
   199				}
   200			}
   201		}
   202	
   203		// If no requirements found, return empty requirements
   204		if requirements == nil {
   205			requirements = &choices.Requirements{}
   206		}
   207	
   208		return &GetRequirementsOutput{
   209			Requirements: requirements,
   210		}, nil
   211	}
